type Query = { query?: string; page?: number };

type QueryParams = Query & Record<string, string | number | boolean>;

type Movie = {
  adult: boolean;
  backdrop_path: string;
  budget: number;
  genre_ids: number[];
  genres: Genre[];
  homepage: string;
  id: number;
  origin_country: string[];
  original_language: string;
  original_title: string;
  overview: string;
  popularity: number;
  poster_path: string;
  production_companies: ProductionCompany[];
  production_countries: ProductionCountry[];
  release_date: string;
  revenue: number;
  runtime: number;
  status: string;
  tagline: string;
  title: string;
  video: boolean;
  vote_average: number;
  vote_count: number;
};

type Genre = {
  id: number;
  name: string;
};

type ProductionCompany = {
  id: number;
  logo_path: string | null;
  name: string;
  origin_country: string;
};

type ProductionCountry = {
  iso_3166_1: string;
  name: string;
};

type GenreMap = Record<number, string>;
